724: fn build_chunks(
725:     rows: &mut [Row],
726:     recomb: &RecombMap,
727:     chunk_rows: usize,
728:     chunk_stride: usize,
729: ) -> Result<Chunks> {
730:     let seq_len = rows[0].input_ids.len();
731:     rows.sort_by(|a, b| {
732:         (a.shard_id, a.node_id, (a.tree_start * 1e6) as i64).cmp(&(
733:             b.shard_id,
734:             b.node_id,
735:             (b.tree_start * 1e6) as i64,
736:         ))
737:     });
738:     let mut groups: HashMap<(i64, i32), Vec<usize>> = HashMap::new();
739:     for (idx, row) in rows.iter().enumerate() {
740:         groups
741:             .entry((row.shard_id, row.node_id))
742:             .or_default()
743:             .push(idx);
744:     }
745:     let mut specs = Vec::new();
746:     for idxs in groups.values() {
747:         let mut start = 0;
748:         while start < idxs.len() {
749:             let end = (start + chunk_rows).min(idxs.len());
750:             specs.push(idxs[start..end].to_vec());
751:             if start + chunk_rows >= idxs.len() {
752:                 break;
753:             }
754:             start += chunk_stride;
755:         }
756:     }
757:     let n_chunks = specs.len();
758:     let mut ids = vec![0i64; n_chunks * chunk_rows * seq_len];
759:     let mut tmrca = vec![0i16; n_chunks * chunk_rows * seq_len * seq_len];
760:     let mut labels = vec![-100i64; n_chunks * chunk_rows];
761:     let mut mask = vec![0u8; n_chunks * chunk_rows];
762:     let mut cm = vec![0f32; n_chunks * chunk_rows * 2];
763:     for (c, idxs) in specs.iter().enumerate() {
764:         let mut prev_start_cm: Option<f64> = None;
765:         for (pos, &ri) in idxs.iter().enumerate() {
766:             let row = &rows[ri];
767:             let id0 = (c * chunk_rows + pos) * seq_len;
768:             ids[id0..id0 + seq_len].copy_from_slice(&row.input_ids);
769:             let m0 = (c * chunk_rows + pos) * seq_len * seq_len;
770:             tmrca[m0..m0 + seq_len * seq_len].copy_from_slice(&row.tmrca);
771:             labels[c * chunk_rows + pos] = row.label;
772:             mask[c * chunk_rows + pos] = 1;
773:             let start_cm = recomb.at_bp(row.tree_start);
774:             let end_cm = recomb.at_bp(row.tree_end);
775:             let cm0 = (c * chunk_rows + pos) * 2;
776:             cm[cm0] = (end_cm - start_cm).max(0.0) as f32;
777:             cm[cm0 + 1] = prev_start_cm.map(|p| start_cm - p).unwrap_or(0.0) as f32;
778:             prev_start_cm = Some(start_cm);
779:         }
780:     }
781:     Ok(Chunks {
782:         input_ids: Array3::from_shape_vec((n_chunks, chunk_rows, seq_len), ids)?,
783:         tmrca: Array4::from_shape_vec((n_chunks, chunk_rows, seq_len, seq_len), tmrca)?,
784:         labels: Array2::from_shape_vec((n_chunks, chunk_rows), labels)?,
785:         row_mask: Array2::from_shape_vec((n_chunks, chunk_rows), mask)?,
786:         cm_features: Array3::from_shape_vec((n_chunks, chunk_rows, 2), cm)?,
787:     })

