81: impl RecombMap {
82:     fn from_path(path: &str) -> Result<Self> {
83:         let text =
84:             std::fs::read_to_string(path).with_context(|| format!("read recomb map {path}"))?;
85:         let mut lines = text.lines().filter(|l| !l.trim().is_empty());
86:         let header: Vec<String> = lines
87:             .next()
88:             .ok_or_else(|| anyhow!("empty recomb map"))?
89:             .split_whitespace()
90:             .map(|s| s.to_string())
91:             .collect();
92:         let pos_idx = find_col(&header, &["position", "Position.bp."])
93:             .unwrap_or(3.min(header.len().saturating_sub(1)));
94:         let map_idx = find_col(
95:             &header,
96:             &[
97:                 "Genetic_Map(cM)",
98:                 "Genetic_Map.cM.",
99:                 "Genetic_Map.cM",
100:                 "map_cM",
101:                 "cM",
102:                 "Map.cM.",
103:             ],
104:         );
105:         let rate_idx = find_col(
106:             &header,
107:             &[
108:                 "COMBINED_rate(cM/Mb)",
109:                 "rate",
110:                 "Rate(cM/Mb)",
111:                 "recomb_rate",
112:                 "Rate.cM.Mb.",
113:             ],
114:         );
115:         let mut rows = Vec::new();
116:         for line in lines {
117:             let f: Vec<&str> = line.split_whitespace().collect();
118:             if f.len() <= pos_idx {
119:                 continue;
120:             }
121:             let pos = f[pos_idx].parse::<f64>()?;
122:             let cm = match map_idx {
123:                 Some(idx) if f.len() > idx => Some(f[idx].parse::<f64>()?),
124:                 _ => None,
125:             };
126:             let rate = match rate_idx {
127:                 Some(idx) if f.len() > idx => Some(f[idx].parse::<f64>()?),
128:                 _ => None,
129:             };
130:             rows.push((pos, cm, rate));
131:         }
132:         rows.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
133:         if rows.is_empty() {
134:             bail!("recombination map has no data rows");
135:         }
136:         let pos: Vec<f64> = rows.iter().map(|x| x.0).collect();
137:         let cm: Vec<f64> = if rows.iter().all(|x| x.1.is_some()) {
138:             rows.iter().map(|x| x.1.unwrap()).collect()
139:         } else if rows.iter().all(|x| x.2.is_some()) {
140:             let mut out = vec![0.0f64; rows.len()];
141:             for i in 1..rows.len() {
142:                 let rate_morgans_per_bp = rows[i - 1].2.unwrap() / 1e8;
143:                 out[i] = out[i - 1] + rate_morgans_per_bp * (pos[i] - pos[i - 1]) * 100.0;
144:             }
145:             out
146:         } else {
147:             bail!("recomb map must include either cumulative cM or rate column");
148:         };
149:         Ok(Self { pos, cm })
150:     }
151: 
152:     fn at_bp(&self, bp: f64) -> f64 {
153:         if self.pos.is_empty() {
154:             return 0.0;
155:         }
156:         if bp <= self.pos[0] {
157:             return self.cm[0];
158:         }
159:         let n = self.pos.len();
160:         if bp >= self.pos[n - 1] {
161:             return self.cm[n - 1];
162:         }
163:         let hi = self.pos.partition_point(|p| *p < bp);
164:         let lo = hi - 1;
165:         let span = self.pos[hi] - self.pos[lo];
166:         if span <= 0.0 {
167:             return self.cm[lo];
168:         }
169:         self.cm[lo] + (bp - self.pos[lo]) / span * (self.cm[hi] - self.cm[lo])
170:     }

